import { test, mock } from 'node:test';
import assert from 'node:assert/strict';
import {
  encodeCookieName,
  encodeCookieValue,
  removeCookie,
  serializeCookie,
  setCookie,
} from '../../src/utils/cookies.ts';

// Golden strings were generated by js-cookie@3.0.5 (`Cookies.set` / `Cookies.remove`)
// against a recording `document` at Date.now() = 1_700_000_000_000, so the native
// helper is proven byte-for-byte identical to what SMOL shipped before.
const NOW = 1_700_000_000_000;
const PLUS_30_DAYS = 'Thu, 14 Dec 2023 22:13:20 GMT';
const MINUS_1_DAY = 'Mon, 13 Nov 2023 22:13:20 GMT';

function recorder() {
  const writes: string[] = [];
  return {
    writes,
    target: {
      get cookie() {
        return '';
      },
      set cookie(v: string) {
        writes.push(v);
      },
    },
  };
}

test('session cookie on smol.xyz: domain, path, secure, sameSite, 30-day expiry', () => {
  mock.method(Date, 'now', () => NOW);
  try {
    const { writes, target } = recorder();
    setCookie(
      'smol_token',
      'eyJ.a-b_c.d',
      { path: '/', secure: true, sameSite: 'Lax', domain: '.smol.xyz', expires: 30 },
      target
    );
    assert.deepEqual(writes, [
      `smol_token=eyJ.a-b_c.d; path=/; secure; sameSite=Lax; domain=.smol.xyz; expires=${PLUS_30_DAYS}`,
    ]);
  } finally {
    mock.restoreAll();
  }
});

test('host-only http (localhost/E2E): secure=false and no domain are omitted', () => {
  assert.equal(
    serializeCookie('smol_token', 'jwt', { path: '/', secure: false, sameSite: 'Lax', expires: 30 }, NOW),
    `smol_token=jwt; path=/; sameSite=Lax; expires=${PLUS_30_DAYS}`
  );
});

test('path defaults to "/" and an absolute Date expiry is serialised as UTC', () => {
  assert.equal(
    serializeCookie('a', 'b', { expires: new Date(NOW) }),
    'a=b; path=/; expires=Tue, 14 Nov 2023 22:13:20 GMT'
  );
});

test('deletion matches js-cookie remove(): empty value, same scope, expires one day ago', () => {
  mock.method(Date, 'now', () => NOW);
  try {
    const { writes, target } = recorder();
    removeCookie('smol_token', { path: '/', secure: true, sameSite: 'Lax', domain: '.smol.xyz' }, target);
    removeCookie('smol_token', { path: '/' }, target);
    assert.deepEqual(writes, [
      `smol_token=; path=/; secure; sameSite=Lax; domain=.smol.xyz; expires=${MINUS_1_DAY}`,
      `smol_token=; path=/; expires=${MINUS_1_DAY}`,
    ]);
  } finally {
    mock.restoreAll();
  }
});

test('RFC 6265 encoding of name and value identical to js-cookie', () => {
  assert.equal(encodeCookieName('we(ird) name;='), 'we%28ird%29%20name%3B%3D');
  assert.equal(encodeCookieName('a#$&+^`|b'), 'a#$&+^`|b');
  assert.equal(
    encodeCookieValue('v a;l,u"e\\%€+/:<=>?@[]^`{|}'),
    'v%20a%3Bl%2Cu%22e%5C%25%E2%82%AC+/:<=>?@[]^`{|}'
  );
});

test('attribute values are truncated at ";" (no attribute injection)', () => {
  assert.equal(
    serializeCookie('n', 'v', { domain: 'x.com;evil=1', path: '/a;secure' }),
    'n=v; path=/a; domain=x.com'
  );
});

test('no document (SSR / Node) is a safe no-op', () => {
  assert.equal(setCookie('a', 'b', {}, null), undefined);
  assert.equal(removeCookie('a', {}, null), undefined);
});
